{
  "summary": "2023 Lincoln Nautilus ADAS: automatic emergency braking and pre-collision warning fail to engage, and the vehicle cannot fully stop under full-force braking at 20 mph or less, with intermittent warnings and auto-park sensor delays.",
  "group": "adas",
  "symptoms": [
    "vehicle cannot come to a full stop under full-force emergency braking at 20 mph or less",
    "Automatic Emergency Braking and pre-collision warning failed to engage",
    "pre-collision warning intermittently activates",
    "auto parking sensors give delayed warnings",
    "vehicle does not brake when dangerously close to objects during auto parking",
    "loud grinding noise from brake pads under full braking",
    "increased braking distance and occasional grinding noise when braking"
  ],
  "conditions": [
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": true,
  "missing_info": [
    "mileage",
    "date"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "FORWARD COLLISION AVOIDANCE: AUTOMATIC EMERGENCY BRAKING"
    },
    {
      "kind": "symptom",
      "quote": "During an emergency break, when applying full force to the break, and the vehicle is traveling at 20 or less mph, the vehicle cannot come to a full stop."
    },
    {
      "kind": "symptom",
      "quote": "Automatic Emergency Braking and pre-collision warning failed to engage."
    },
    {
      "kind": "condition",
      "quote": "Under the same condition, pre-collision warning would sometimes be activated and sometimes doesn't."
    },
    {
      "kind": "symptom",
      "quote": "When using the car's auto parking feature, multiple sensors would have delayed warnings, and the car will not break when getting dangerously close to objects."
    },
    {
      "kind": "symptom",
      "quote": "increased break distance and occasion grinding noise when breaking (regardless of the speed)"
    },
    {
      "kind": "safety",
      "quote": "the vehicle cannot come to a full stop"
    }
  ]
}

